#include <bits/stdc++.h>
using namespace std;

// Drzewo trie na małych literach: wstawianie, liczba słów z prefiksem, liczba wystąpień słowa.
struct Trie {
    vector<array<int, 26>> next;   // next[v][c] = syn węzła v po literze c (0 = brak)
    vector<int> passCount;         // ile słów przechodzi przez węzeł (= ma ten prefiks)
    vector<int> endCount;          // ile słów kończy się w węźle

    Trie() { newNode(); }          // węzeł 0 = korzeń
    int newNode() {
        next.push_back({});        // same zera
        passCount.push_back(0);
        endCount.push_back(0);
        return (int)next.size() - 1;
    }
    void insert(const string& s) {
        int v = 0;
        passCount[v]++;
        for (char ch : s) {
            int c = ch - 'a';
            if (next[v][c] == 0) { int u = newNode(); next[v][c] = u; }
            v = next[v][c];
            passCount[v]++;
        }
        endCount[v]++;
    }
    int findNode(const string& s) const {   // węzeł odpowiadający s albo -1
        int v = 0;
        for (char ch : s) {
            v = next[v][ch - 'a'];
            if (v == 0) return -1;
        }
        return v;
    }
    int countPrefix(const string& p) const { int v = findNode(p); return v == -1 ? 0 : passCount[v]; }
    int countWord(const string& w) const { int v = findNode(w); return v == -1 ? 0 : endCount[v]; }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, q;
    cin >> n >> q;
    Trie trie;
    for (int i = 0; i < n; i++) {
        string w;
        cin >> w;
        trie.insert(w);
    }
    while (q--) {
        string p;
        cin >> p;
        cout << trie.countPrefix(p) << ' ' << trie.countWord(p) << '\n';   // ile z prefiksem p, ile równych p
    }
}

#include <bits/stdc++.h>
using namespace std;

// Trie binarne na liczbach do 2^30: maksymalny XOR z liczbą x.
struct XorTrie {
    static const int BITS = 30;
    vector<array<int, 2>> next;
    vector<int> cnt;               // ile liczb w poddrzewie (pozwala usuwać)

    XorTrie() { next.push_back({0, 0}); cnt.push_back(0); }
    void insert(int x, int delta = 1) {   // delta = -1 usuwa (liczba musi być w trie)
        int v = 0;
        cnt[v] += delta;
        for (int b = BITS - 1; b >= 0; b--) {
            int bit = (x >> b) & 1;
            if (next[v][bit] == 0) {
                next.push_back({0, 0});
                cnt.push_back(0);
                next[v][bit] = (int)next.size() - 1;
            }
            v = next[v][bit];
            cnt[v] += delta;
        }
    }
    int maxXor(int x) const {      // max (x ^ y) po y w trie; trie niepuste
        int v = 0, res = 0;
        for (int b = BITS - 1; b >= 0; b--) {
            int want = ((x >> b) & 1) ^ 1;          // chcemy przeciwny bit
            int u = next[v][want];
            if (u != 0 && cnt[u] > 0) { res |= 1 << b; v = u; }
            else v = next[v][want ^ 1];
        }
        return res;
    }
};

int main() {
    int n;
    cin >> n;
    vector<int> a(n);
    for (auto& x : a) cin >> x;
    XorTrie trie;
    trie.insert(a[0]);
    int best = 0;
    for (int i = 1; i < n; i++) {        // max po parach i < j
        best = max(best, trie.maxXor(a[i]));
        trie.insert(a[i]);
    }
    cout << best << '\n';
}

