#include <bits/stdc++.h>
using namespace std;

// DSU z cofaniem: łączenie według rozmiaru, BEZ kompresji ścieżek, stos zmian.
struct RollbackDSU {
    vector<int> parent, size_;
    vector<pair<int, int>> history;   // (dołączony korzeń, korzeń, do którego dołączono); (-1, -1) = brak zmiany
    int components;

    RollbackDSU(int n) : parent(n), size_(n, 1), components(n) { iota(parent.begin(), parent.end(), 0); }

    int find(int x) const {            // O(log n) dzięki łączeniu według rozmiaru
        while (parent[x] != x) x = parent[x];
        return x;
    }
    bool unite(int a, int b) {
        a = find(a), b = find(b);
        if (a == b) { history.push_back({-1, -1}); return false; }
        if (size_[a] > size_[b]) swap(a, b);
        parent[a] = b;
        size_[b] += size_[a];
        components--;
        history.push_back({a, b});
        return true;
    }
    int snapshot() const { return history.size(); }
    void rollback(int snap) {          // cofnij do stanu z snapshot()
        while ((int)history.size() > snap) {
            auto [a, b] = history.back();
            history.pop_back();
            if (a == -1) continue;
            parent[a] = a;
            size_[b] -= size_[a];
            components++;
        }
    }
};

int main() {
    int n, q;
    cin >> n >> q;
    RollbackDSU dsu(n + 1);
    vector<int> saved;                     // stos punktów zapisu
    while (q--) {
        char type;
        cin >> type;
        if (type == 'u') {                 // u a b: połącz
            int a, b;
            cin >> a >> b;
            dsu.unite(a, b);
        } else if (type == 'q') {          // q a b: czy w jednej składowej
            int a, b;
            cin >> a >> b;
            cout << (dsu.find(a) == dsu.find(b) ? "TAK" : "NIE") << '\n';
        } else if (type == 's') {          // s: zapamiętaj stan
            saved.push_back(dsu.snapshot());
        } else {                           // r: cofnij do ostatniego zapisu
            dsu.rollback(saved.back());
            saved.pop_back();
        }
    }
    cout << dsu.components - 1 << '\n';    // składowe wśród 1..n (wierzchołek 0 nieużywany)
}

