struct TimeSegTree {
    int T;
    vector<vector<pair<int, int>>> edges;
    TimeSegTree(int T) : T(T), edges(4 * T) {}
    void addEdge(int v, int tl, int tr, int l, int r, pair<int, int> e) {   // krawędź żyje w [l, r]
