#include <bits/stdc++.h>
using namespace std;

// Treap (drzewo + kopiec) z kluczami, dopuszcza duplikaty. Węzeł 0 = pusty.
mt19937 treapRng(712367);

struct Treap {
    struct Node {
        int key;
        unsigned prio;
        int size, left, right;
    };
    vector<Node> t;
    int root = 0;

    Treap() { t.push_back({0, 0, 0, 0, 0}); }
    int sz(int v) const { return t[v].size; }
    void pull(int v) { t[v].size = 1 + sz(t[v].left) + sz(t[v].right); }

    // dzieli drzewo v na: l = klucze < key, r = klucze >= key
    void split(int v, int key, int& l, int& r) {
        if (v == 0) { l = r = 0; return; }
        if (t[v].key < key) { split(t[v].right, key, t[v].right, r); l = v; }
        else { split(t[v].left, key, l, t[v].left); r = v; }
        pull(v);
    }
    // łączy drzewa l i r, gdzie wszystkie klucze l <= klucze r
    int merge(int l, int r) {
        if (l == 0 || r == 0) return l ? l : r;
        if (t[l].prio > t[r].prio) { t[l].right = merge(t[l].right, r); pull(l); return l; }
        t[r].left = merge(l, t[r].left);
        pull(r);
        return r;
    }
    void insert(int key) {
        t.push_back({key, (unsigned)treapRng(), 1, 0, 0});
        int node = (int)t.size() - 1, a, b;
        split(root, key, a, b);
        root = merge(merge(a, node), b);
    }
    void eraseOne(int key) {                       // usuwa jedną kopię key (jeśli jest)
        int a, b, c;
        split(root, key, a, b);                    // a < key <= b
        split(b, key + 1, b, c);                   // b == key, c > key
        if (b) b = merge(t[b].left, t[b].right);   // wyrzucamy korzeń b
        root = merge(merge(a, b), c);
    }
    int countLess(int key) const {                 // ile kluczy < key
        int v = root, res = 0;
        while (v) {
            if (t[v].key < key) { res += sz(t[v].left) + 1; v = t[v].right; }
            else v = t[v].left;
        }
        return res;
    }
    int kth(int k) const {                         // k-ty najmniejszy (k od 1); -1 gdy k > size
        int v = root;
        while (v) {
            int leftSize = sz(t[v].left);
            if (k <= leftSize) v = t[v].left;
            else if (k == leftSize + 1) return t[v].key;
            else { k -= leftSize + 1; v = t[v].right; }
        }
        return -1;
    }
    int size() const { return sz(root); }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int q;
    cin >> q;
    Treap tr;
    while (q--) {
        int type, x;
        cin >> type >> x;
        if (type == 1) tr.insert(x);                     // wstaw x
        else if (type == 2) tr.eraseOne(x);              // usuń jedną kopię x
        else if (type == 3) cout << tr.kth(x) << '\n';   // x-ty najmniejszy (albo -1)
        else cout << tr.countLess(x) << '\n';            // ile < x
    }
}

#include <bits/stdc++.h>
using namespace std;

// Treap niejawny (klucz = pozycja): odwracanie fragmentu tablicy w O(log n).
mt19937 implicitRng(91823);

struct ImplicitTreap {
    vector<int> value, left, right, size;
    vector<unsigned> prio;
    vector<char> rev;                // leniwe odwrócenie poddrzewa
    int root = 0;

    ImplicitTreap() { newNode(0); size[0] = 0; }   // węzeł 0 = pusty
    int newNode(int x) {
        value.push_back(x); left.push_back(0); right.push_back(0); size.push_back(1);
        prio.push_back(implicitRng()); rev.push_back(0);
        return (int)value.size() - 1;
    }
    void pull(int v) { size[v] = 1 + size[left[v]] + size[right[v]]; }
    void push(int v) {
        if (v && rev[v]) {
            swap(left[v], right[v]);
            if (left[v]) rev[left[v]] ^= 1;
            if (right[v]) rev[right[v]] ^= 1;
            rev[v] = 0;
        }
    }
    void split(int v, int k, int& l, int& r) {      // l = pierwsze k elementów
        if (!v) { l = r = 0; return; }
        push(v);
        if (size[left[v]] < k) { split(right[v], k - size[left[v]] - 1, right[v], r); l = v; }
        else { split(left[v], k, l, left[v]); r = v; }
        pull(v);
    }
    int merge(int l, int r) {
        if (!l || !r) return l ? l : r;
        if (prio[l] > prio[r]) { push(l); right[l] = merge(right[l], r); pull(l); return l; }
        push(r);
        left[r] = merge(l, left[r]);
        pull(r);
        return r;
    }
    void pushBack(int x) { int v = newNode(x); root = merge(root, v); }
    void reverse(int l, int r) {                    // odwróć pozycje [l, r], 0-indeksowane
        int a, b, c;
        split(root, l, a, b);
        split(b, r - l + 1, b, c);
        if (b) rev[b] ^= 1;
        root = merge(merge(a, b), c);
    }
    void collect(int v, vector<int>& out) {
        if (!v) return;
        push(v);
        collect(left[v], out);
        out.push_back(value[v]);
        collect(right[v], out);
    }
};

int main() {
    int n, q;
    cin >> n >> q;
    ImplicitTreap tr;
    for (int i = 0; i < n; i++) {
        int x;
        cin >> x;
        tr.pushBack(x);
    }
    while (q--) {
        int l, r;                    // odwróć a[l..r], 1-indeksowane
        cin >> l >> r;
        tr.reverse(l - 1, r - 1);
    }
    vector<int> out;
    tr.collect(tr.root, out);
    for (size_t i = 0; i < out.size(); i++) cout << out[i] << " \n"[i + 1 == out.size()];
}

