        return -1;
    }
    int size() const { return sz(root); }
};

// Treap niejawny (klucz = pozycja): odwracanie fragmentu tablicy w O(log n).
mt19937 implicitRng(91823);

struct ImplicitTreap {
    vector<int> value, left, right, size;
    vector<unsigned> prio;
    vector<char> rev;                // leniwe odwrócenie poddrzewa
    int root = 0;

    ImplicitTreap() { newNode(0); size[0] = 0; }   // węzeł 0 = pusty
    int newNode(int x) {
        value.push_back(x); left.push_back(0); right.push_back(0); size.push_back(1);
        prio.push_back(implicitRng()); rev.push_back(0);
        return (int)value.size() - 1;
    }
    void pull(int v) { size[v] = 1 + size[left[v]] + size[right[v]]; }
    void push(int v) {
        if (v && rev[v]) {
            swap(left[v], right[v]);
            if (left[v]) rev[left[v]] ^= 1;
            if (right[v]) rev[right[v]] ^= 1;
            rev[v] = 0;
        }
    }
    void split(int v, int k, int& l, int& r) {      // l = pierwsze k elementów
        if (!v) { l = r = 0; return; }
        push(v);
        if (size[left[v]] < k) { split(right[v], k - size[left[v]] - 1, right[v], r); l = v; }
        else { split(left[v], k, l, left[v]); r = v; }
        pull(v);
    }
    int merge(int l, int r) {
        if (!l || !r) return l ? l : r;
        if (prio[l] > prio[r]) { push(l); right[l] = merge(right[l], r); pull(l); return l; }
        push(r);
        left[r] = merge(l, left[r]);
        pull(r);
        return r;
    }
    void pushBack(int x) { int v = newNode(x); root = merge(root, v); }
    void reverse(int l, int r) {                    // odwróć pozycje [l, r], 0-indeksowane
        int a, b, c;
        split(root, l, a, b);
        split(b, r - l + 1, b, c);
        if (b) rev[b] ^= 1;
        root = merge(merge(a, b), c);
    }
    void collect(int v, vector<int>& out) {
        if (!v) return;
        push(v);
        collect(left[v], out);
        out.push_back(value[v]);
        collect(right[v], out);
    }
};

