// Hashowanie wielomianowe modulo dwóch liczb pierwszych; porównanie podsłów w O(1).
struct StringHash {
    static constexpr long long MOD1 = 1000000007, MOD2 = 998244353;
    vector<long long> h1, h2, p1, p2;   // h[i] = hash prefiksu s[0..i-1]

    StringHash(const string& s, long long base) {
        int n = s.size();
        h1.assign(n + 1, 0); h2.assign(n + 1, 0);
        p1.assign(n + 1, 1); p2.assign(n + 1, 1);
        for (int i = 0; i < n; i++) {
            long long c = (unsigned char)s[i] + 1;   // znak nigdy nie ma wartości 0
            h1[i + 1] = (h1[i] * base + c) % MOD1;
            h2[i + 1] = (h2[i] * base + c) % MOD2;
            p1[i + 1] = p1[i] * base % MOD1;
            p2[i + 1] = p2[i] * base % MOD2;
        }
    }
    pair<long long, long long> get(int l, int r) const {   // hash s[l..r), półotwarty
        long long x1 = (h1[r] - h1[l] * p1[r - l]) % MOD1;
        long long x2 = (h2[r] - h2[l] * p2[r - l]) % MOD2;
        if (x1 < 0) x1 += MOD1;
        if (x2 < 0) x2 += MOD2;
        return {x1, x2};
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    string s;
    int q;
    cin >> s >> q;
    mt19937 rng(chrono::steady_clock::now().time_since_epoch().count());
    long long base = uniform_int_distribution<long long>(300, 1000000000)(rng);   // losowa podstawa > alfabet
    StringHash hs(s, base);
    while (q--) {
        int a, b, c, d;                  // czy s[a..b] == s[c..d], 1-indeksowane
        cin >> a >> b >> c >> d;
        bool equal = (b - a == d - c) && hs.get(a - 1, b) == hs.get(c - 1, d);
        cout << (equal ? "TAK" : "NIE") << '\n';
    }
}

