const unsigned long long MOD61 = (1ULL << 61) - 1;
unsigned long long mulMod61(unsigned long long a, unsigned long long b) {
    __uint128_t c = (__uint128_t)a * b;
    unsigned long long res = (unsigned long long)(c & MOD61) + (unsigned long long)(c >> 61);
    if (res >= MOD61) res -= MOD61;
    return res;
}
unsigned long long addMod61(unsigned long long a, unsigned long long b) {
    unsigned long long res = a + b;
    if (res >= MOD61) res -= MOD61;
    return res;
}

// LCP sufiksów zaczynających się w i i j; hs — StringHash dla s, n = |s|
int lcp(const vector<long long>& h, const vector<long long>& p, long long mod, int n, int i, int j) {
    auto get = [&](int l, int r) { long long x = (h[r] - h[l] * p[r - l]) % mod; return x < 0 ? x + mod : x; };
    int lo = 0, hi = n - max(i, j);          // odpowiedź w [lo, hi]
    while (lo < hi) {
        int mid = lo + (hi - lo + 1) / 2;
        if (get(i, i + mid) == get(j, j + mid)) lo = mid;
        else hi = mid - 1;
    }
    return lo;
}

vector<int> occurrences(const string& text, const string& pat) {
    const long long M = 1000000007, B = 131;
    int n = text.size(), m = pat.size();
    vector<int> res;
    if (m > n) return res;
    long long hp = 0, ht = 0, pw = 1;
    for (int i = 0; i < m; i++) {
        hp = (hp * B + pat[i]) % M;
        ht = (ht * B + text[i]) % M;
        if (i > 0) pw = pw * B % M;          // B^(m-1)
    }
    for (int i = 0; ; i++) {
        if (ht == hp && text.compare(i, m, pat) == 0) res.push_back(i);   // weryfikacja = zero kolizji
        if (i + m >= n) break;
        ht = (ht - text[i] * pw % M + M) % M;     // usuń znak z lewej
        ht = (ht * B + text[i + m]) % M;          // dodaj znak z prawej
    }
    return res;
}

